contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    receive() external payable {}

    function run(address callee, bytes memory data, bool callSucceeds) public payable {
        // Decide the expected outcome: if callee has code, its execution result is
        // whatever the caller says via callSucceeds; if callee has no code, a low-level
        // call always succeeds.
        require(callee.code.length > 0 || callSucceeds, "no-code callee must succeed");
        // If callee has code, callSucceeds must match whether callee.call(data) would succeed.
        if (callee.code.length > 0) {
            (bool probe, ) = callee.call(data);
            require(probe == callSucceeds, "callSucceeds must match probe");
        }

        bool reverted;
        try c.forward(callee, data) { reverted = false; } catch { reverted = true; }

        // forward reverts exactly when the underlying callee.call(data) fails.
        assert(reverted == !callSucceeds);
    }
}

