contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    event Received();

    function run(address badCallee, bytes memory data) public payable {
        // Precondition: badCallee uses a fixed selector that has no fallback and will revert.
        require(badCallee != address(0), "badCallee must be nonzero");

        // Choose a deliberately non-existent function selector on badCallee. A call to it must revert.
        bytes memory badData = hex"deadbeef";
        require(data.length >= 0, "data always valid");

        // Forward to a known-reverting callee; this call changes c's state (by making an external call)
        // and must revert because the forwarded call fails.
        bool reverted;
        try c.forward(badCallee, badData) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: forwarding to a callee whose call always fails always makes forward revert.
        assert(reverted);
    }

    receive() external payable {}
}

